from src.nodes.base import BaseNode
from src.runtime.assets.assembly.collision_detector import get_collision_detector
from src.runtime.assets.assembly.spatial_metadata import SpatialMetadata
import json

class Hou_Mcp_Collision_Review(BaseNode):
    name = "hou_mcp_collision_review"

    def __init__(self):
        super().__init__()
        # [AUTO-GENERATED-PORTS-START]
        self.add_input("placements_json", "string", widget_type="text", default="[]")
        self.add_input("environment",     "string", widget_type="text", default="")
        self.add_output("collision_report_json", "string")
        self.add_output("collision_count",       "int")
        self.add_output("ok",                    "bool")
        # [AUTO-GENERATED-PORTS-END]

    async def execute(self, inputs):
        placements_json = str(inputs.get("placements_json", "[]") or "[]")
        try:
            raw = json.loads(placements_json)
        except Exception as exc:
            self.log_error(f"Failed to parse placements_json: {exc}")
            return {"collision_report_json": "{}", "collision_count": 0, "ok": True, "exec_out": True}

        try:
            placements = []
            for item in raw:
                aid  = str(item.get("asset_id", ""))
                pos  = tuple(item.get("position", [0.0, 0.0, 0.0]))
                meta = SpatialMetadata.from_dict(item.get("spatial_metadata") or {})
                placements.append((aid, pos, meta))

            report = get_collision_detector().validate_scene(placements)
            self.log_info(f"Collision review: {report.collision_count} collision(s). ok={report.ok}")
            if not report.ok:
                for pair in report.pairs[:3]:
                    self.log_warning(f"  Collision: {pair.asset_a} ↔ {pair.asset_b} overlap={pair.separation_needed:.2f}m")
            return {
                "collision_report_json": json.dumps(report.to_dict(), sort_keys=True, default=str),
                "collision_count":       report.collision_count,
                "ok":                    report.ok,
                "exec_out": True,
            }
        except Exception as exc:
            self.log_error(f"Collision review failed: {exc}")
            return {"collision_report_json": "{}", "collision_count": 0, "ok": True, "exec_out": True}

def register_node():
    return Hou_Mcp_Collision_Review
